<?php
namespace App\Http\Controllers\Api;

use App\Http\Controllers\Controller;
use App\Support\LegacyResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Symfony\Component\HttpFoundation\StreamedResponse;
use Throwable;

class ReportController extends Controller
{
    private function breakdownBase(Request $r)
    {
        $q=DB::table('breakdowns as b')->join('equipment as e','e.id','=','b.equipment_id')->leftJoin('shift_logs as sl','sl.id','=','b.shift_log_id');
        if($r->filled('from_date'))$q->whereDate('b.start_time','>=',$r->input('from_date'));
        if($r->filled('to_date'))$q->whereDate('b.start_time','<=',$r->input('to_date'));
        if($r->filled('plant'))$q->where('e.plant',$r->input('plant'));
        if($r->filled('shift'))$q->where('sl.shift',$r->input('shift'));
        if($r->filled('department'))$q->where('e.department',$r->input('department'));
        if($r->filled('status'))$q->where('b.status',$r->input('status'));
        if($r->filled('equipment')){$s=strtolower($r->input('equipment'));$q->where(function($x)use($s){$x->whereRaw('LOWER(e.name) LIKE ?', ["%$s%"])->orWhereRaw('LOWER(e.code) LIKE ?', ["%$s%"]);});}
        return $q;
    }
    public function breakdowns(Request $r){try{$base=$this->breakdownBase($r);$total=(clone $base)->count();$open=(clone $base)->where('b.status','OPEN')->count();$closed=(clone $base)->where('b.status','CLOSED')->count();$closedQ=(clone $base)->where('b.status','CLOSED');$kpi=['total'=>$total,'open'=>$open,'closed'=>$closed,'total_downtime_min'=>round((float)((clone $closedQ)->sum('b.downtime_minutes')?:0)),'avg_mttr_min'=>round((float)((clone $closedQ)->avg('b.downtime_minutes')?:0)),'equipment_affected'=>(clone $base)->distinct()->count('b.equipment_id')];$q=$this->breakdownBase($r)->leftJoin('stop_reasons as sr','sr.id','=','b.initial_reason_id')->leftJoin('users as u1','u1.id','=','sl.operator_id')->leftJoin('users as u2','u2.id','=','b.closed_by')->select('b.bd_number','e.name as equipment_name','e.code as equipment_code','e.department','e.plant','sl.shift','sr.description as reason','sr.category as reason_category','b.status','b.start_time','b.end_time','b.downtime_minutes','b.findings','b.actions_taken','b.spares_used','b.resolution_notes','u1.full_name as reported_by','u2.full_name as closed_by');$data=$q->orderByDesc('b.start_time')->limit(1000)->get()->map(fn($x)=>LegacyResponse::normalize($x))->all();return response()->json(['success'=>true,'kpi'=>$kpi,'data'=>$data]);}catch(Throwable $e){return $this->err($e);}}

    private function jobBase(Request $r){$q=DB::table('jobs as j');if($r->filled('from_date'))$q->whereDate('j.created_at','>=',$r->input('from_date'));if($r->filled('to_date'))$q->whereDate('j.created_at','<=',$r->input('to_date'));if($r->filled('plant'))$q->where('j.plant',$r->input('plant'));if($r->filled('shift'))$q->where('j.shift',$r->input('shift'));if($r->filled('department'))$q->where('j.assigned_dept',$r->input('department'));if($r->filled('status'))$q->where('j.status',$r->input('status'));return $q;}
    public function jobs(Request $r){try{$b=$this->jobBase($r);$kpi=['total'=>(clone $b)->count(),'open'=>(clone $b)->where('j.status','OPEN')->count(),'assigned'=>(clone $b)->where('j.status','ASSIGNED')->count(),'in_progress'=>(clone $b)->where('j.status','IN PROGRESS')->count(),'completed'=>(clone $b)->where('j.status','COMPLETED')->count(),'closed'=>(clone $b)->where('j.status','CLOSED')->count(),'from_stoppage'=>(clone $b)->whereNotNull('j.description')->count(),'depts_involved'=>(clone $b)->distinct()->count('j.assigned_dept')];$q=$this->jobBase($r)->leftJoin('equipment as e','e.id','=','j.equipment_id')->leftJoin('users as u1','u1.id','=','j.raised_by')->leftJoin('users as u2','u2.id','=','j.assigned_to')->select('j.job_number','j.title','j.description','j.plant','j.shift','j.status','j.assigned_dept','j.remarks','j.created_at','j.assigned_at','j.completed_at','j.closed_at','e.name as equipment_name','e.code as equipment_code','e.department as equipment_dept','u1.full_name as raised_by','u1.department as raised_by_dept','u2.full_name as assigned_to');$data=$q->orderByDesc('j.created_at')->limit(1000)->get()->map(fn($x)=>LegacyResponse::normalize($x))->all();return response()->json(['success'=>true,'kpi'=>$kpi,'data'=>$data]);}catch(Throwable $e){return $this->err($e);}}

    public function parameters(Request $r){try{$q=DB::table('eq_monitoring_logs as pl')->leftJoin('equipment as e','e.id','=','pl.equipment_id')->leftJoin('equipment_monitoring_types as emt','emt.id','=','pl.monitoring_id')->leftJoin('users as u','u.id','=','pl.logged_by')->select('pl.*','e.name as equipment_name','e.code as equipment_code','emt.monitoring_name as parameter_name','emt.reference_values','u.full_name as logged_by_name');if($r->filled('from_date'))$q->whereDate('pl.logged_at','>=',$r->input('from_date'));if($r->filled('to_date'))$q->whereDate('pl.logged_at','<=',$r->input('to_date'));if($r->filled('plant'))$q->where('pl.plant',$r->input('plant'));if($r->filled('shift'))$q->where('pl.shift',$r->input('shift'));if($r->filled('department'))$q->where('pl.department',$r->input('department'));$logs=$q->orderByDesc('pl.logged_at')->limit(2000)->get();$kpi=['total_readings'=>$logs->count(),'equipment_count'=>$logs->pluck('equipment_id')->unique()->count(),'operators_count'=>$logs->pluck('logged_by')->unique()->count(),'days_covered'=>$logs->map(fn($x)=>substr((string)$x->logged_at,0,10))->unique()->count()];$data=[];foreach($logs as $log){$read=is_string($log->readings)?json_decode($log->readings,true):$log->readings;$ref=is_string($log->reference_values)?json_decode($log->reference_values,true):$log->reference_values;if(!is_array($read))$read=[];foreach($read as $rd){$data[]=['logged_at'=>$log->logged_at,'plant'=>$log->plant,'department'=>$log->department,'shift'=>$log->shift,'equipment_name'=>$log->equipment_name,'equipment_code'=>$log->equipment_code,'parameter_name'=>$log->parameter_name,'unit'=>$rd['unit']??'','actual_value'=>$rd['value']??null,'standard_value_snapshot'=>is_string($log->reference_values)?$log->reference_values:json_encode($ref),'standard_value'=>$ref[0]['value']??null,'reading_remarks'=>$log->remarks,'logged_by'=>$log->logged_by_name];}}return response()->json(['success'=>true,'kpi'=>$kpi,'data'=>$data]);}catch(Throwable $e){return $this->err($e);}}

    public function shiftDuty(Request $r){try{$q=DB::table('shift_logs as sl')->join('equipment as e','e.id','=','sl.equipment_id')->join('users as u','u.id','=','sl.operator_id')->selectRaw('DATE(sl.logged_at) AS duty_date, sl.shift, e.plant, u.department, u.full_name AS shift_incharge, COUNT(DISTINCT sl.id) AS entries_logged, MIN(sl.logged_at) AS first_entry, MAX(sl.logged_at) AS last_entry');if($r->filled('from_date'))$q->whereDate('sl.logged_at','>=',$r->input('from_date'));if($r->filled('to_date'))$q->whereDate('sl.logged_at','<=',$r->input('to_date'));if($r->filled('plant'))$q->where('e.plant',$r->input('plant'));if($r->filled('shift'))$q->where('sl.shift',$r->input('shift'));if($r->filled('department'))$q->where('u.department',$r->input('department'));$rows=$q->groupByRaw('DATE(sl.logged_at), sl.shift, e.plant, u.department, u.full_name')->orderByDesc('duty_date')->orderBy('sl.shift')->orderBy('e.plant')->orderBy('u.department')->get()->all();return response()->json(['success'=>true,'data'=>$rows]);}catch(Throwable $e){return $this->err($e);}}

    private function gsjBase(Request $r){$q=DB::table('general_shift_jobs as g');if($r->filled('from_date'))$q->whereDate('g.created_at','>=',$r->input('from_date'));if($r->filled('to_date'))$q->whereDate('g.created_at','<=',$r->input('to_date'));if($r->filled('plant'))$q->where('g.plant',$r->input('plant'));if($r->filled('department'))$q->where('g.department',$r->input('department'));if($r->filled('status'))$q->where('g.status',$r->input('status'));return $q;}
    public function generalShiftJobs(Request $r){try{$b=$this->gsjBase($r);$closed=(clone $b)->whereNotNull('g.closed_at')->selectRaw('AVG(TIMESTAMPDIFF(SECOND,g.created_at,g.closed_at)/86400) a')->value('a');$kpi=['total'=>(clone $b)->count(),'open'=>(clone $b)->where('g.status','OPEN')->count(),'in_progress'=>(clone $b)->where('g.status','IN PROGRESS')->count(),'completed'=>(clone $b)->where('g.status','COMPLETED')->count(),'closed'=>(clone $b)->where('g.status','CLOSED')->count(),'avg_completion_days'=>round((float)($closed?:0)),'depts_involved'=>(clone $b)->distinct()->count('g.department'),'plants_covered'=>(clone $b)->distinct()->count('g.plant')];$q=$this->gsjBase($r)->leftJoin('users as u1','u1.id','=','g.raised_by')->leftJoin('users as u2','u2.id','=','g.closed_by')->select('g.job_number','g.title','g.description','g.status','g.department','g.plant','g.remarks','g.created_at','g.started_at','g.completed_at','g.closed_at','u1.full_name as raised_by_name','u2.full_name as closed_by_name')->selectRaw('TIMESTAMPDIFF(SECOND,g.created_at,g.closed_at)/86400 AS completion_days')->selectRaw("CASE WHEN g.status='OPEN' AND g.created_at < DATE_SUB(NOW(), INTERVAL 7 DAY) THEN 'overdue' WHEN g.status='IN PROGRESS' AND g.created_at < DATE_SUB(NOW(), INTERVAL 14 DAY) THEN 'overdue' ELSE 'on_track' END AS health_status");return response()->json(['success'=>true,'kpi'=>$kpi,'data'=>$q->orderByDesc('g.created_at')->limit(2000)->get()->all()]);}catch(Throwable $e){return $this->err($e);}}

    public function departmentGsj(Request $r,string $dept){$u=$r->attributes->get('jwt_user');if($u->role==='maintenance'&&$u->department!==$dept)return response()->json(['success'=>false,'message'=>'You can only view your own department reports'],403);try{$base=DB::table('general_shift_jobs as g')->where('g.department',$dept);if($r->filled('from_date'))$base->whereDate('g.created_at','>=',$r->input('from_date'));if($r->filled('to_date'))$base->whereDate('g.created_at','<=',$r->input('to_date'));$raw=(clone $base)->selectRaw("DATE_FORMAT(g.created_at,'%Y-%m') AS month, COUNT(*) AS total_jobs, SUM(CASE WHEN g.status='CLOSED' THEN 1 ELSE 0 END) AS closed_jobs, ROUND(AVG(TIMESTAMPDIFF(SECOND,g.created_at,g.closed_at)/86400),1) AS avg_days_to_close")->groupByRaw("DATE_FORMAT(g.created_at,'%Y-%m')")->orderByDesc('month')->limit(12)->get()->all();$open=(clone $base)->select('g.job_number','g.title','g.created_at','g.status')->selectRaw('TIMESTAMPDIFF(SECOND,g.created_at,NOW())/86400 AS age_days')->whereIn('g.status',['OPEN','IN PROGRESS'])->orderBy('g.created_at')->get()->map(fn($x)=>(array)$x)->all();return response()->json(['success'=>true,'data'=>['department'=>$dept,'monthly_performance'=>$raw,'open_jobs'=>$open,'summary'=>['total_open'=>count(array_filter($open,fn($j)=>$j['status']==='OPEN')),'total_in_progress'=>count(array_filter($open,fn($j)=>$j['status']==='IN PROGRESS'))]]]);}catch(Throwable $e){return $this->err($e);}}

    public function exportGsj(Request $r){try{$q=$this->gsjBase($r)->leftJoin('users as u1','u1.id','=','g.raised_by')->leftJoin('users as u2','u2.id','=','g.closed_by')->select('g.job_number','g.title','g.description','g.status','g.department','g.plant','g.created_at','g.started_at','g.completed_at','g.closed_at','u1.full_name as raised_by','u2.full_name as closed_by')->selectRaw('TIMESTAMPDIFF(SECOND,g.created_at,g.closed_at)/86400 AS completion_days')->orderByDesc('g.created_at');$rows=$q->get();$filename='general_shift_jobs_'.now()->format('Y-m-d').'.csv';return response()->streamDownload(function()use($rows){$f=fopen('php://output','w');fputcsv($f,['Job Number','Title','Description','Status','Department','Plant','Created At','Started At','Completed At','Closed At','Raised By','Closed By','Completion Days']);foreach($rows as $x)fputcsv($f,[$x->job_number,$x->title,$x->description,$x->status,$x->department,$x->plant,$x->created_at,$x->started_at,$x->completed_at,$x->closed_at,$x->raised_by,$x->closed_by,$x->completion_days]);fclose($f);},$filename,['Content-Type'=>'text/csv']);}catch(Throwable $e){return $this->err($e);}}
    private function err(Throwable $e){return response()->json(['success'=>false,'message'=>$e->getMessage()],500);}
}
